import{_t as e,at as t,et as n,n as r,rt as i}from"./chunks/framework.GGfqtSwG.js";var a=JSON.parse(`{"title":"Om guiden","description":"","frontmatter":{},"headers":[],"relativePath":"omguiden.md","filePath":"omguiden.md"}`),o={name:`omguiden.md`};function s(r,a,o,s,c,l){return e(),i(`div`,null,[...a[0]||=[n(`h1`,{id:`om-guiden`,tabindex:`-1`},[t(`Om guiden `),n(`a`,{class:`header-anchor`,href:`#om-guiden`,"aria-label":`Permalink to “Om guiden”`},`​`)],-1),n(`p`,null,`Jeg skrev denne guide, fordi jeg har snakket med mange transpersoner her i Danmark som sidder fast på CKI's ventelister, og ikke alle er klar over, at der er andre muligheder, eller er overvældet af, hvor kompliceret og skræmmende det kan virke. Målet er at samle den bedste information og organiserer det for at gøre det overskueligt.`,-1),n(`p`,null,`Da testosteron er vurderet som et dopingmiddel af Lægemiddelstyrelsen, er det ulovligt at besidde uden recept. Så selvom jeg rigtig gerne ville, så kan denne guide derfor ikke dække DIY maskuliniserende hormonbehandling.`,-1),n(`p`,null,[t(`Alt i guiden er skrevet ud fra mine egne oplevelser og ud fra samtaler jeg har haft med andre transpersoner. Jeg har ikke nogen medicinsk uddannelse og guiden kan have fejl. Hvis du finder noget som er forkert eller hvis du har information du vil tilføje, send en mail til `),n(`a`,{href:`mailto:dktransguide@pm.me`,target:`_blank`,rel:`noreferrer`},`dktransguide@pm.me`),t(`.`)],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};